import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
// 1. 新增 Eye 和 EyeOff 圖示
import { Mail, Lock, ArrowRight, AlertCircle, Eye, EyeOff } from 'lucide-react';

const Login = () => {
  const navigate = useNavigate();
  const logoUrl = "data:image/png;base64,";

  const [formData, setFormData] = useState({ email: '', password: '' });
  const [error, setError] = useState(null);

  // 2. 新增顯示/隱藏密碼的狀態
  const [showPassword, setShowPassword] = useState(false);

  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  const handleSubmit = (e) => {
    e.preventDefault();
    setError(null);

    if (!emailRegex.test(formData.email)) return setError('請輸入有效的 Email 格式');
    if (formData.password.length < 6) return setError('密碼長度不正確');

    navigate('/');
  };

  return (
    <div className="min-h-screen bg-zinc-50 flex flex-col items-center justify-center p-4 font-sans text-zinc-900">
      <div className="w-full max-w-md bg-white border border-zinc-200 rounded-[2.5rem] shadow-xl shadow-zinc-200/50 p-10 relative z-10">
        {/* ... Logo 和 標題 部分保持不變 ... */}
        <div className="text-center mb-10">
          <img src={logoUrl} alt="Logo" className="w-20 h-20 mx-auto mb-4 rounded-2xl shadow-lg" />
          <h1 className="text-3xl font-black tracking-tight">歡迎回來</h1>
          <p className="text-zinc-500 font-medium">繼續您的專業證照挑戰</p>
        </div>

        {error && (
          <div className="mb-6 p-4 bg-red-50 border border-red-100 rounded-2xl flex items-center gap-3 text-red-600 text-sm font-bold">
            <AlertCircle size={18} /> {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-5">
          <div className="relative">
            <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-400" size={20} />
            <input
              type="email" required placeholder="Email 地址"
              className="w-full pl-12 pr-4 py-4 bg-zinc-50 border border-zinc-200 rounded-2xl focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all font-medium"
              onChange={e => setFormData({...formData, email: e.target.value})}
            />
          </div>

          <div className="relative">
            <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-400" size={20} />
            <input
              // 3. 根據狀態動態更改 type
              type={showPassword ? "text" : "password"}
              required
              placeholder="密碼"
              className="w-full pl-12 pr-12 py-4 bg-zinc-50 border border-zinc-200 rounded-2xl focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all font-medium"
              onChange={e => setFormData({...formData, password: e.target.value})}
            />

            {/* 4. 新增切換按鈕 */}
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-4 top-1/2 -translate-y-1/2 text-zinc-400 hover:text-zinc-600 transition-colors"
            >
              {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
            </button>
          </div>

          <div className="flex justify-end">
            <Link to="/forgotPassword" size="sm" className="text-sm font-bold text-indigo-600 hover:text-indigo-700">忘記密碼？</Link>
          </div>

          <button type="submit" className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-2xl shadow-lg shadow-indigo-600/20 flex items-center justify-center gap-2 transition-all active:scale-95">
            登入帳號 <ArrowRight size={18} />
          </button>
        </form>

        <div className="mt-10 text-center">
          <p className="text-zinc-500 font-medium">
            還沒有帳號嗎？
            <Link to="/register" className="ml-2 text-indigo-600 font-bold underline underline-offset-4">立即免費註冊</Link>
          </p>
        </div>
      </div>
    </div>
  );
};

export default Login;
