import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { Mail, Lock, User, ArrowRight, Eye, EyeOff, AlertCircle, ShieldCheck } from 'lucide-react';

const Register = () => {
  const navigate = useNavigate();
  const logoUrl = "data:image/png;base64,";

  const [formData, setFormData] = useState({ name: '', email: '', password: '', confirmPassword: '', otp: '' });

  // --- 修改處 1: 拆分顯示密碼的狀態 ---
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  const [error, setError] = useState(null);
  const [countdown, setCountdown] = useState(0);
  const [isSending, setIsSending] = useState(false);

  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  const passwordRegex = /^(?=.*[A-Za-z])(?=.*\d)[A-Za-z\d]{8,}$/;

  useEffect(() => {
    if (countdown > 0) {
      const timer = setTimeout(() => setCountdown(countdown - 1), 1000);
      return () => clearTimeout(timer);
    }
  }, [countdown]);

  const handleSendOTP = () => {
    if (!emailRegex.test(formData.email)) {
      setError('請先輸入有效的 Email 格式以接收驗證碼');
      return;
    }
    setError(null);
    setIsSending(true);
    setTimeout(() => {
      setIsSending(false);
      setCountdown(60);
      alert('驗證碼已發送到您的電子信箱');
    }, 1000);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setError(null);
    if (!formData.name.trim()) return setError('請輸入您的姓名');
    if (!emailRegex.test(formData.email)) return setError('電子郵件格式不正確');
    if (!formData.otp.trim()) return setError('請輸入驗證碼');
    if (!passwordRegex.test(formData.password)) return setError('密碼需至少 8 位並包含英文字母與數字');
    if (formData.password !== formData.confirmPassword) return setError('兩次密碼輸入不一致');
    navigate('/login');
  };

  return (
    <div className="min-h-screen bg-zinc-50 flex flex-col items-center justify-center p-4 font-sans text-zinc-900">
      <div className="w-full max-w-md bg-white border border-zinc-200 rounded-[2.5rem] shadow-xl shadow-zinc-200/50 p-10 relative z-10">
        <div className="text-center mb-8">
          <img src={logoUrl} alt="Logo" className="w-20 h-20 mx-auto mb-4 rounded-2xl shadow-lg" />
          <h1 className="text-3xl font-black tracking-tight mb-2">建立新帳號</h1>
          <p className="text-zinc-500 font-medium">加入我們，開啟你的專業挑戰</p>
        </div>

        {error && (
          <div className="mb-6 p-4 bg-red-50 border border-red-100 rounded-2xl flex items-center gap-3 text-red-600 text-sm font-bold">
            <AlertCircle size={18} /> {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          {/* 姓名與 Email 欄位省略，保持原樣 */}
          <div className="relative">
            <User className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-400" size={20} />
            <input type="text" required placeholder="您的真實姓名" className="w-full pl-12 pr-4 py-4 bg-zinc-50 border border-zinc-200 rounded-2xl focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all font-medium" onChange={e => setFormData({...formData, name: e.target.value})} />
          </div>
          <div className="relative">
            <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-400" size={20} />
            <input type="email" required placeholder="電子郵件地址" className="w-full pl-12 pr-4 py-4 bg-zinc-50 border border-zinc-200 rounded-2xl focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all font-medium" onChange={e => setFormData({...formData, email: e.target.value})} />
          </div>

          {/* 驗證碼欄位保持原樣 */}
          <div className="flex gap-3">
            <div className="relative flex-1">
              <ShieldCheck className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-400" size={20} />
              <input type="text" required placeholder="驗證碼" className="w-full pl-12 pr-4 py-4 bg-zinc-50 border border-zinc-200 rounded-2xl focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all font-medium" onChange={e => setFormData({...formData, otp: e.target.value})} />
            </div>
            <button type="button" disabled={countdown > 0 || isSending} onClick={handleSendOTP} className="px-6 py-4 bg-zinc-900 text-white font-bold rounded-2xl text-sm transition-all hover:bg-zinc-800 disabled:bg-zinc-200 whitespace-nowrap min-w-[100px]">
              {countdown > 0 ? `${countdown}s` : isSending ? "發送中" : "發送驗證碼"}
            </button>
          </div>

          {/* --- 修改處 2: 設定密碼 (獨立開關) --- */}
          <div className="relative">
            <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-400" size={20} />
            <input
              type={showPassword ? "text" : "password"}
              required
              placeholder="設定密碼 (英數 8 位)"
              className="w-full pl-12 pr-12 py-4 bg-zinc-50 border border-zinc-200 rounded-2xl focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all font-medium"
              onChange={e => setFormData({...formData, password: e.target.value})}
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-4 top-1/2 -translate-y-1/2 text-zinc-400 hover:text-indigo-600 transition-colors"
            >
              {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
            </button>
          </div>

          {/* --- 修改處 3: 確認密碼 (獨立開關) --- */}
          <div className="relative">
            <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-400" size={20} />
            <input
              type={showConfirmPassword ? "text" : "password"}
              required
              placeholder="再次確認密碼"
              className="w-full pl-12 pr-12 py-4 bg-zinc-50 border border-zinc-200 rounded-2xl focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all font-medium"
              onChange={e => setFormData({...formData, confirmPassword: e.target.value})}
            />
            <button
              type="button"
              onClick={() => setShowConfirmPassword(!showConfirmPassword)}
              className="absolute right-4 top-1/2 -translate-y-1/2 text-zinc-400 hover:text-indigo-600 transition-colors"
            >
              {showConfirmPassword ? <EyeOff size={20} /> : <Eye size={20} />}
            </button>
          </div>

          <button type="submit" className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-2xl shadow-lg shadow-indigo-600/20 flex items-center justify-center gap-2 transition-all active:scale-95 mt-4">
            註冊並開始學習 <ArrowRight size={18} />
          </button>
        </form>

        <p className="mt-8 text-center text-zinc-500 font-medium">
          已經有帳號了？
          <Link to="/login" className="text-indigo-600 font-bold ml-1 hover:underline underline-offset-4">立即登入</Link>
        </p>
      </div>
    </div>
  );
};

export default Register;
